def max_levels_of_nesting(paren_string: str) -> int:
    """ Given a string represented multiple groups for nested parentheses, return the deepest level of nesting.
    For each group, if there is no parenthesis, assume that it's not nested (no parentheses -> depth = 0).

    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> max_levels_of_nesting('(()()) ((())) () ((())()())')
    3
    """
    open_bracket_count = 0
    for char in paren_string:
        if char == '(':
            open_bracket_count += 1
        elif char == ')':
            open_bracket_count -= 1

    return open_bracket_count


